        e_phoff = buffer.readUInt32LE(offset);
        offset += 4;
        e_shoff = buffer.readUInt32LE(offset);
        offset += 4;
        e_flags = buffer.readUInt32LE(offset);
        offset += 4;
        e_ehsize = buffer.readUInt16LE(offset);
        offset += 2;
        e_phentsize = buffer.readUInt16LE(offset);
        offset += 2;
        e_phnum = buffer.readUInt16LE(offset);
        offset += 2;
        e_shentsize = buffer.readUInt16LE(offset);
        offset += 2;
        e_shnum = buffer.readUInt16LE(offset);
