            sh_name = buffer.readUInt32LE(shOffset);
            sh_type = buffer.readUInt32LE(shOffset + 4);
            sh_flags = buffer.readBigUInt64LE(shOffset + 8);
            sh_addr = buffer.readBigUInt64LE(shOffset + 16);
            sh_offset = buffer.readBigUInt64LE(shOffset + 24);
            sh_size = buffer.readBigUInt64LE(shOffset + 32);
            sh_link = buffer.readUInt32LE(shOffset + 40);
            sh_info = buffer.readUInt32LE(shOffset + 44);
            sh_addralign = buffer.readBigUInt64LE(shOffset + 48);
            sh_entsize = buffer.readBigUInt64LE(shOffset + 56);
        } else {
            sh_name = buffer.readUInt32LE(shOffset);
            sh_type = buffer.readUInt32LE(shOffset + 4);
            sh_flags = buffer.readUInt32LE(shOffset + 8);
            sh_addr = buffer.readUInt32LE(shOffset + 12);
            sh_offset = buffer.readUInt32LE(shOffset + 16);
            sh_size = buffer.readUInt32LE(shOffset + 20);
            sh_link = buffer.readUInt32LE(shOffset + 24);
            sh_info = buffer.readUInt32LE(shOffset + 28);
            sh_addralign = buffer.readUInt32LE(shOffset + 32);
            sh_entsize = buffer.readUInt32LE(shOffset + 36);
        }

        sections.push({
            name: sh_name,
            type: sh_type,
            flags: sh_flags,
            addr: sh_addr,
            offset: sh_offset,
            size: sh_size,
            link: sh_link,
            info: sh_info,
            addralign: sh_addralign,
            entsize: sh_entsize
        });
    }

    // Get section header string table
    const shstrtabSection = sections[e_shstrndx];
    const shstrtab = buffer.slice(shstrtabSection.offset, shstrtabSection.offset + shstrtabSection.size);

