            name += String.fromCharCode(shstrtab[strOffset]);
            strOffset++;
        }
        section.name = name;
    }

    // Find .data and .bss sections and extract values
    const dataSection = sections.find(s => s.name === '.data');
    const bssSection = sections.find(s => s.name === '.bss');

    // Extract 32-bit values from .data section
    if (dataSection && dataSection.size > 0) {
        const dataStart = Number(dataSection.offset);
        const dataSize = Number(dataSection.size);

        for (let i = 0; i + 4 <= dataSize; i += 4) {
            const addr = Number(dataSection.addr) + i;
            const value = buffer.readUInt32LE(dataStart + i);
            result[addr.toString()] = value;
        }
    }

    // Extract 32-bit values from .bss section (treat as zeros)
    if (bssSection && bssSection.size > 0) {
        const bssStart = Number(bssSection.offset);
        const bssSize = Number(bssSection.size);

        for (let i = 0; i + 4 <= bssSize; i += 4) {
            const addr = Number(bssSection.addr) + i;
            result[addr.toString()] = 0;
        }
    }

    return result;
